<script setup lang="ts">
import {ref,watch,onUnmounted,useId} from 'vue';
import type {Client,Page} from '@briochett/contracts';
import {api,errorMessage} from '../api';
import Pagination from './Pagination.vue';
const emit=defineEmits<{select:[client:Client]}>(),q=ref(''),page=ref(1),data=ref<Page<Client>>({items:[],total:0,page:1,pageSize:20}),busy=ref(false),error=ref(''),listId=useId();let timer:ReturnType<typeof setTimeout>,controller:AbortController|undefined;
async function load(){controller?.abort();controller=new AbortController();const current=controller;busy.value=true;error.value='';try{const response=await api<Page<Client>>('/clients?active=true&page='+page.value+'&q='+encodeURIComponent(q.value),{signal:controller.signal});if(current===controller)data.value=response;}catch(e){if(!(e instanceof DOMException&&e.name==='AbortError'))error.value=errorMessage(e);}finally{if(current===controller)busy.value=false;}}
watch(q,()=>{page.value=1;clearTimeout(timer);timer=setTimeout(load,300);});watch(page,load);load();onUnmounted(()=>{clearTimeout(timer);controller?.abort();});
</script>
<template><div class="stack"><p class="muted">Busca por nombre comercial, código o RIF. Solo aparecen clientes activos de tu alcance.</p><label>Buscar cliente<input v-model="q" type="search" placeholder="Nombre, código o RIF…" autocomplete="off" role="combobox" :aria-expanded="true" :aria-controls="listId" /></label><p v-if="error" class="notice error" role="alert">{{error}} <button class="text-button" @click="load">Reintentar</button></p><p v-if="busy" role="status">Buscando clientes…</p><div :id="listId" class="search-results" role="listbox" aria-label="Clientes encontrados"><button v-for="client in data.items" :key="client.id" class="client-result secondary" role="option" :aria-selected="false" @click="emit('select',client)"><strong>{{client.name}}</strong><span>{{client.code}} · {{client.rif||'RIF pendiente'}}</span><small>{{client.zone||'Sin zona'}} · {{client.sellerName||'Sin vendedor asignado'}}</small></button></div><p v-if="!busy&&!data.items.length" class="empty">No encontramos clientes. Prueba otro nombre, código o RIF.</p><Pagination :page="page" :total="data.total" :busy="busy" @change="page=$event" /></div></template>
